'use strict';

/* ATLAS AML 0.44.8 · Entity route authority
 * Root cause fixed: v019Navigate retained a closure over the pre-Entity360
 * loadEntities function. The 0.44.7 CSS correctly hid that legacy white landing,
 * which exposed an empty page when the legacy route was still invoked.
 *
 * 2026-09-04 navigation hardening:
 * Entering `entities` is now a true fresh-start action. Any previously selected
 * Entity 360 dossier, persistent autocomplete host, suggestions and query text
 * are cleared before the current search workspace is mounted. The empty Entity
 * 360 dossier generated by the workspace authority is then removed so the user
 * sees only a clean search surface until a new entity is selected.
 *
 * This late classic authority routes only `entities` to the current governed
 * Entity 360 entry. Every other route is delegated unchanged. It does not touch
 * Auth, Supabase session state, RLS, refresh tokens or analytical semantics.
 */
(function atlasEntityRouteAuthority0448(){
  const RELEASE='0.44.8';
  const BUILD='0448';
  const ENTRY=window.__ATLAS_ENTITY_ENTRY__;
  if(!ENTRY||typeof ENTRY.load!=='function'){
    window.__ATLAS_ENTITY_ROUTE_0448__={active:false,reason:'entity-entry-unavailable',installedAt:new Date().toISOString()};
    return;
  }

  const previousNavigate=typeof window.navigate==='function'?window.navigate:null;
  const baseEntityLoad=ENTRY.load.bind(ENTRY);

  function entityContent(){
    try{
      if(typeof v019Content==='function')return v019Content();
    }catch(_error){}
    return document.querySelector('#content');
  }

  function clearPriorEntityState(){
    try{
      if(typeof state!=='undefined'){
        state.view='entities';
        state.selectedEntity=null;
      }
    }catch(_error){}

    /* The 0.44.7 search host lives outside #content by design. Remove it here
       so returning to Entidades cannot reuse the previous entity/query state. */
    try{document.querySelector('#a47-entity-search-host')?.remove();}catch(_error){}

    const c=entityContent();
    if(c)try{c.replaceChildren();}catch(_error){c.innerHTML='';}
  }

  function enforceCleanSearchSurface(){
    const c=entityContent();
    /* ENTRY.load mounts its historical empty dossier. The Entidades menu must
       instead be search-first, so keep the freshly mounted search host and clear
       the dossier until the analyst selects a new entity. */
    if(c)try{c.replaceChildren();}catch(_error){c.innerHTML='';}

    const host=document.querySelector('#a47-entity-search-host');
    if(host){
      host.classList.remove('busy');
      const input=host.querySelector('#a47-entity-q');
      if(input){
        input.value='';
        input.disabled=false;
      }
      const status=host.querySelector('#a47-search-status');
      if(status)status.textContent='Escribe al menos 2 caracteres para recibir sugerencias.';
      const selected=host.querySelector('#a47-selected');
      if(selected)selected.innerHTML='';
      const suggestions=host.querySelector('#a47-suggestions');
      if(suggestions){suggestions.innerHTML='';suggestions.hidden=true;}
      host.querySelector('.a47-combobox')?.setAttribute('aria-expanded','false');
      setTimeout(()=>input?.focus(),0);
    }

    window.__ATLAS_ENTITY360_CURRENT__={
      ...(window.__ATLAS_ENTITY360_CURRENT__||{}),
      mode:'entities-clean-search',
      selectedEntity:null,
      cleanEntry:true,
      renderedAt:new Date().toISOString()
    };
  }

  async function entityLoad(...args){
    clearPriorEntityState();
    const result=await baseEntityLoad(...args);
    enforceCleanSearchSurface();
    return result;
  }

  async function navigate0448(view,...args){
    if(view==='entities')return entityLoad(...args);
    if(previousNavigate)return previousNavigate(view,...args);
  }

  /* Global classic identifiers and window properties are pinned together because
     historical shell listeners call the identifier `navigate` dynamically. */
  try{navigate=navigate0448;}catch(_error){}
  window.navigate=navigate0448;
  try{loadEntities=entityLoad;}catch(_error){}
  window.loadEntities=entityLoad;
  ENTRY.load=entityLoad;

  ENTRY.version='0448';
  ENTRY.release=RELEASE;
  ENTRY.routeAuthority='ENTITY360_ROUTE_AUTHORITY_0448';
  ENTRY.legacyLandingBypassed=true;
  ENTRY.entitiesEntryPolicy='CLEAN_SEARCH_NO_PERSISTED_ENTITY360';

  window.__ATLAS_ENTITY_ROUTE_0448__={
    active:true,
    release:RELEASE,
    build:BUILD,
    authority:'ENTITY360_ROUTE_AUTHORITY_0448',
    entitiesRoute:'CLEAN_SEARCH_CURRENT_ENTRY',
    cleanSearchOnEveryEntry:true,
    previousEntityCleared:true,
    legacyCapturedLoaderBypassed:true,
    authMutation:false,
    installedAt:new Date().toISOString()
  };
})();